class GrowingList {
    private var items = IntArray(2)
    var size = 0
        private set
    var copies = 0
        private set

    fun add(value: Int) {
        if (size == items.size) {
            items = items.copyOf(items.size * 2)
            copies += size
        }
        items[size] = value
        size++
    }
}

fun main() {
    val list = GrowingList()
    for (n in 1..8) {
        list.add(n)
    }
    println("Size: ${list.size}")
    println("Items copied in total: ${list.copies}")
}

